482	    /// Gate new arms and abort every armed task, without awaiting quiescence
483	    /// and without releasing the owned runtime.
484	    ///
485	    /// The prologue shared by [`Self::shutdown`], [`Self::begin_close`] and
486	    /// `Drop`. It lives in one place because three callers that each spelled
487	    /// out the same three `retain`s is one rule known in three places, and a
488	    /// rule held equal only by diligence has already drifted or will: a fourth
489	    /// task kind added to one copy and not the others would leave an epoch that
490	    /// reports itself closed while a task of that kind is still running.
491	    fn gate_and_abort(&self) {
492	        self.shutting_down.store(true, Ordering::Release);
493	        self.watches.retain(|_, handle| {
494	            handle.abort();
495	            false
496	        });
497	        self.spawn_retries.retain(|_, handle| {
498	            handle.abort();
499	            false
500	        });
501	        self.completion_retries.retain(|_, handle| {
502	            handle.abort();
503	            false
504	        });
505	    }
