507	    /// Close the epoch to new and in-flight durable writes without blocking.
508	    ///
509	    /// This is the non-blocking half of [`Self::shutdown`], for `Drop` paths
510	    /// that may run inside a host async context where a blocking join would
511	    /// panic. It states its own limit: it **gates and aborts, it does not
512	    /// await**. A task already past the append boundary is cancelled at its
513	    /// next await point rather than before its current store call returns.
514	    /// Callers needing abort-AND-await must use [`Self::shutdown`].
515	    pub(crate) fn begin_close(&self) {
516	        self.gate_and_abort();
517	    }
518	}
