520	/// Sleep the current backoff, then advance it up the ladder toward `ceiling`.
521	///
522	/// Shared by every engine background task that retries a durable write, so the
523	/// cadence is one rule in one place rather than a constant re-chosen per call
524	/// site. It takes the ceiling rather than a whole policy struct on purpose: the
525	/// callers no longer agree on WHICH policy governs them — signal delivery bounds
526	/// an enqueue wait, completion retry bounds a durable store round-trip — and a
527	/// helper that named one of those types would quietly re-couple them.
528	pub(crate) async fn sleep_backoff(current: &mut std::time::Duration, ceiling: std::time::Duration) {
529	    tokio::time::sleep(*current).await;
530	    let doubled = current.saturating_mul(2);
531	    *current = if doubled > ceiling { ceiling } else { doubled };
532	}
