534	/// Shut the owned runtime down and wait for its worker to finish in-flight
535	/// polls, from any calling context.
536	fn shutdown_runtime_and_join(runtime: tokio::runtime::Runtime) {
537	    // Dropping a `Runtime` inside an async context panics; spawn a plain
538	    // thread to perform the blocking drop and join it. The drop cancels all
539	    // remaining tasks and waits for in-flight polls to complete, which is
540	    // exactly the quiescence guarantee the epoch close needs.
541	    match std::thread::Builder::new()
542	        .name("aion-engine-tasks-shutdown".to_owned())
543	        .spawn(move || drop(runtime))
544	    {
545	        Ok(joiner) => {
546	            if joiner.join().is_err() {
547	                tracing::error!("engine-task runtime shutdown thread panicked");
548	            }
549	        }
550	        Err(error) => {
551	            // The runtime moved into the closure and is dropped by the failed
552	            // spawn itself, on THIS thread. That is the one path where the drop
553	            // is not isolated, so it is reported rather than described as a
554	            // graceful fallback: from an async context it can panic, and an
555	            // operator seeing this line needs to know the epoch close did not
556	            // get the thread it asked for.
557	            tracing::error!(
558	                error = %error,
559	                "could not spawn the engine-task runtime shutdown thread; the \
560	                 runtime was dropped on the calling thread instead"
561	            );
562	        }
563	    }
564	}
