async fn drop_backstop_aborts_without_blocking() -> TestResult {
    let flag = Arc::new(AtomicBool::new(false));
    {
        let tasks = EngineTaskRuntime::new()?;
        assert_eq!(
            tasks.arm_watch(12, WorkflowId::new_v4(), park_forever(Arc::clone(&flag))),
            ArmOutcome::Armed
        );
